def kernel_cholesky(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Scratch buffer for reciprocals of the diagonal:
    #   inv_diag[j] = 1 / A[j, j] after row j is finished.
    # This turns O(n^2) divisions in the off-diagonal updates into
    # O(n^2) multiplications plus only O(n) divisions.
    inv_diag: DATA_TYPE[n]

    for i in seq(0, n):
        # ------------------------------------------------------------
        # Off-diagonal elements in row i: 0 <= j < i.
        # Original kernel:
        #   for j in 0..i-1:
        #     for k in 0..j-1: A[i,j] -= A[i,k] * A[j,k]
        #     A[i,j] /= A[j,j]
        #
        # Here we:
        #   * Keep A[i,j] in a scalar accumulator acc_ij held in a register,
        #     so we only load A[i,j] once and store it once per (i,j).
        #   * Replace the division by a multiplication with a cached
        #     reciprocal inv_diag[j].
